/**
 * 详情的内容契约（ADR 0013）：header、notices、可选 tabs、正文、可选 aside，加上三个状态分支与可折叠段。
 * 整页和抽屉共用这一份；本文件不 import `Sheet*`，只有 `DetailTitle` 读呈现 context。
 *
 * - 没有页脚。编辑态的提交与取消放进 header 的 `actions`，表单正文放进正文位（表单模板）。
 * - aside 按容器宽度降级，不按视口：容器窄时折到正文下方。
 * - 不取数，不 import 路由库：链接是宿主解析好的字符串，经链接适配渲染（ADR 0005）。
 */
import {
  ChevronRightIcon,
  FileQuestionIcon,
  MoreHorizontalIcon,
  TriangleAlertIcon,
} from "lucide-react";
import type { ReactNode } from "react";

import { Button } from "@/components/ui/button";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
} from "@/components/ui/empty";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useLinkAdapter } from "../app-shell/link-adapter";
import { DetailTitle } from "./detail-presentation";

// ── header ───────────────────────────────────────────────────────────────────

/** 「更多操作」菜单里的一项。危险项（删除、吊销）写 `destructive`，排在分隔线之后。 */
export type DetailMenuAction = {
  key: string;
  label: string;
  onSelect: () => void;
  destructive?: boolean;
  disabled?: boolean;
};

export type DetailHeaderProps = {
  /** 标题，通常是对象的名字。整页下渲染成 `<h1>`，抽屉下渲染成 `SheetTitle`。 */
  title: ReactNode;
  /** 标题旁的徽标，如状态 `Badge`。 */
  badges?: ReactNode;
  /** 标题下的一句说明。 */
  description?: ReactNode;
  /** 元信息行，如「创建于 …」「负责人 …」。 */
  meta?: ReactNode;
  /** 主、次动作按钮。编辑态时换成表单的「取消」与「保存」（`form={formId}`）。 */
  actions?: ReactNode;
  /** 次要动作与危险动作，收进行尾的「更多操作」菜单。 */
  moreActions?: readonly DetailMenuAction[];
  /** 「更多操作」按钮的 `aria-label`。 */
  moreActionsLabel?: string;
};

export function DetailHeader({
  title,
  badges,
  description,
  meta,
  actions,
  moreActions,
  moreActionsLabel = "更多操作",
}: DetailHeaderProps) {
  const hasMenu = moreActions !== undefined && moreActions.length > 0;
  return (
    <header data-slot="detail-header" className="flex flex-col gap-2">
      <div className="flex flex-wrap items-start gap-3">
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <div className="flex flex-wrap items-center gap-2">
            <DetailTitle className="min-w-0 break-words font-semibold text-foreground text-lg">
              {title}
            </DetailTitle>
            {badges}
          </div>
          {description ? <p className="text-muted-foreground text-xs">{description}</p> : null}
        </div>
        {actions || hasMenu ? (
          <div className="flex shrink-0 flex-wrap items-center gap-2">
            {actions}
            {hasMenu ? <DetailMoreActions actions={moreActions} label={moreActionsLabel} /> : null}
          </div>
        ) : null}
      </div>
      {meta ? (
        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-muted-foreground text-xs">
          {meta}
        </div>
      ) : null}
    </header>
  );
}

function DetailMoreActions({
  actions,
  label,
}: {
  actions: readonly DetailMenuAction[];
  label: string;
}) {
  const regular = actions.filter((action) => !action.destructive);
  const destructive = actions.filter((action) => action.destructive);
  const item = (action: DetailMenuAction) => (
    <DropdownMenuItem
      key={action.key}
      variant={action.destructive ? "destructive" : "default"}
      disabled={action.disabled}
      onClick={action.onSelect}
    >
      {action.label}
    </DropdownMenuItem>
  );
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" size="icon" aria-label={label} />}>
        <MoreHorizontalIcon />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {regular.map(item)}
        {regular.length > 0 && destructive.length > 0 ? <DropdownMenuSeparator /> : null}
        {destructive.map(item)}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

// ── 正文：notices、tabs、aside ─────────────────────────────────────────────────

export type DetailTab = {
  value: string;
  label: string;
  content: ReactNode;
};

type DetailBodyBase = {
  /** 正文上方的提示，如「这条记录已归档」。跨整行，不进 aside。 */
  notices?: ReactNode;
  /** 窄栏：静态元信息（创建时间、负责人）。容器窄时折到正文下方。 */
  aside?: ReactNode;
  /** aside 的 `aria-label`。 */
  asideLabel?: string;
};

type DetailBodyWithTabs = DetailBodyBase & {
  tabs: readonly DetailTab[];
  /** 非受控时的初始标签，缺省第一个。 */
  defaultTab?: string;
  /** 受控：当前标签。要把标签存进地址时用。 */
  tab?: string;
  onTabChange?: (value: string) => void;
  children?: never;
};

type DetailBodyWithoutTabs = DetailBodyBase & {
  tabs?: never;
  defaultTab?: never;
  tab?: never;
  onTabChange?: never;
  children: ReactNode;
};

export type DetailBodyProps = DetailBodyWithTabs | DetailBodyWithoutTabs;

/** 正文与 aside 的排布。`DetailSkeleton` 用同一份，加载完成时布局不跳。 */
function DetailColumns({
  main,
  aside,
  asideLabel,
}: {
  main: ReactNode;
  aside?: ReactNode;
  asideLabel: string;
}) {
  return (
    <div className="flex flex-col gap-6 @3xl:flex-row">
      <div className="flex min-w-0 flex-1 flex-col gap-6">{main}</div>
      {aside ? (
        <aside
          aria-label={asideLabel}
          className="flex flex-col gap-4 border-border border-t pt-6 @3xl:w-64 @3xl:shrink-0 @3xl:border-t-0 @3xl:border-l @3xl:pt-0 @3xl:pl-6"
        >
          {aside}
        </aside>
      ) : null}
    </div>
  );
}

export function DetailBody(props: DetailBodyProps) {
  const { notices, aside, asideLabel = "元信息" } = props;
  const main = props.tabs ? (
    <Tabs
      defaultValue={
        props.tab === undefined ? (props.defaultTab ?? props.tabs[0]?.value) : undefined
      }
      value={props.tab}
      onValueChange={props.onTabChange ? (value) => props.onTabChange?.(String(value)) : undefined}
      className="gap-4"
    >
      <TabsList variant="line">
        {props.tabs.map((tab) => (
          <TabsTrigger key={tab.value} value={tab.value}>
            {tab.label}
          </TabsTrigger>
        ))}
      </TabsList>
      {props.tabs.map((tab) => (
        <TabsContent key={tab.value} value={tab.value} className="flex flex-col gap-6">
          {tab.content}
        </TabsContent>
      ))}
    </Tabs>
  ) : (
    props.children
  );
  return (
    <div data-slot="detail-body" className="@container flex flex-col gap-6">
      {notices ? <div className="flex flex-col gap-2">{notices}</div> : null}
      <DetailColumns main={main} aside={aside} asideLabel={asideLabel} />
    </div>
  );
}

// ── 可折叠段 ───────────────────────────────────────────────────────────────────

export type DetailSectionProps = {
  title: string;
  /** 段内说明，收起时一起收起。 */
  description?: ReactNode;
  /** 段标题右侧的动作，如「查看全部」。 */
  actions?: ReactNode;
  /** 缺省展开。 */
  defaultOpen?: boolean;
  children: ReactNode;
};

/** 正文里的一段，如「基本信息」。标题是按钮，点击收起或展开；段与段之间有分隔线。 */
export function DetailSection({
  title,
  description,
  actions,
  defaultOpen = true,
  children,
}: DetailSectionProps) {
  return (
    <Collapsible
      defaultOpen={defaultOpen}
      className="flex flex-col gap-3 border-border border-t pt-4 first:border-t-0 first:pt-0"
    >
      <div className="flex items-center gap-2">
        <h2 className="min-w-0 flex-1">
          <CollapsibleTrigger className="group/detail-section flex items-center gap-1.5 font-medium text-foreground text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring/50">
            <ChevronRightIcon className="size-4 text-muted-foreground transition-transform duration-150 ease-emphasized group-data-panel-open/detail-section:rotate-90" />
            {title}
          </CollapsibleTrigger>
        </h2>
        {actions}
      </div>
      <CollapsibleContent className="flex flex-col gap-3">
        {description ? <p className="text-muted-foreground text-xs">{description}</p> : null}
        {children}
      </CollapsibleContent>
    </Collapsible>
  );
}

// ── 三个状态分支 ───────────────────────────────────────────────────────────────

/**
 * 加载中。整页下给路由的 pending 用（包在 `DETAIL_MAIN` 里），抽屉下给取数状态用。
 * 标题只给读屏软件，抽屉因此仍有可访问名称。
 */
export function DetailSkeleton({
  label = "加载中…",
  tabs = true,
  aside = true,
}: {
  label?: string;
  /** 详情有标签页时为真，骨架画一条标签栏。 */
  tabs?: boolean;
  /** 详情有 aside 时为真。 */
  aside?: boolean;
}) {
  return (
    <div data-slot="detail-skeleton" aria-busy="true" className="flex flex-col gap-6">
      <DetailTitle className="sr-only">{label}</DetailTitle>
      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-3">
          <Skeleton className="h-7 w-48" />
          <Skeleton className="h-5 w-14" />
          <Skeleton className="ml-auto h-8 w-24" />
        </div>
        <Skeleton className="h-4 w-72 max-w-full" />
      </div>
      <div className="@container flex flex-col gap-6">
        <DetailColumns
          asideLabel={label}
          main={
            <>
              {tabs ? <Skeleton className="h-8 w-64 max-w-full" /> : null}
              <div className="grid grid-cols-1 gap-x-6 gap-y-4 @md:grid-cols-2">
                {["a", "b", "c", "d", "e", "f"].map((key) => (
                  <div key={key} className="flex flex-col gap-1">
                    <Skeleton className="h-3 w-16" />
                    <Skeleton className="h-4 w-40 max-w-full" />
                  </div>
                ))}
              </div>
            </>
          }
          aside={
            aside
              ? ["a", "b", "c"].map((key) => (
                  <div key={key} className="flex flex-col gap-1">
                    <Skeleton className="h-3 w-16" />
                    <Skeleton className="h-4 w-32" />
                  </div>
                ))
              : null
          }
        />
      </div>
    </div>
  );
}

type DetailBackAction =
  | { /** 返回去哪，宿主解析好的字符串。整页用。 */ backHref: string; onBack?: never }
  | { /** 返回动作，如关闭抽屉。抽屉用。 */ onBack: () => void; backHref?: never };

export type DetailNotFoundProps = DetailBackAction & {
  title?: string;
  description?: ReactNode;
  backLabel?: string;
};

/** 不存在或已删除：`Empty` + 返回动作。不要和加载中共用一个分支。 */
export function DetailNotFound({
  title = "找不到这条记录",
  description = "它可能已被删除，或者链接有误。",
  backLabel = "返回",
  ...back
}: DetailNotFoundProps) {
  const { Link } = useLinkAdapter();
  return (
    <Empty data-slot="detail-not-found">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <FileQuestionIcon />
        </EmptyMedia>
        <DetailTitle className="font-medium text-sm">{title}</DetailTitle>
        <EmptyDescription>{description}</EmptyDescription>
      </EmptyHeader>
      <EmptyContent>
        {back.backHref !== undefined ? (
          <Button variant="outline" render={<Link href={back.backHref} />} nativeButton={false}>
            {backLabel}
          </Button>
        ) : (
          <Button variant="outline" onClick={back.onBack}>
            {backLabel}
          </Button>
        )}
      </EmptyContent>
    </Empty>
  );
}

export type DetailErrorProps = {
  title?: string;
  description?: ReactNode;
  /** 重试，如重新取数或 `router.invalidate()`。不传就不显示重试按钮。 */
  onRetry?: () => void;
  retryLabel?: string;
};

/** 取数失败：`Empty` + 重试动作。提交失败不用它，用 `FormError`。 */
export function DetailError({
  title = "加载失败",
  description = "网络或服务出了问题，请稍后重试。",
  onRetry,
  retryLabel = "重试",
}: DetailErrorProps) {
  return (
    <Empty data-slot="detail-error">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <TriangleAlertIcon />
        </EmptyMedia>
        <DetailTitle className="font-medium text-sm">{title}</DetailTitle>
        <EmptyDescription>{description}</EmptyDescription>
      </EmptyHeader>
      {onRetry ? (
        <EmptyContent>
          <Button variant="outline" onClick={onRetry}>
            {retryLabel}
          </Button>
        </EmptyContent>
      ) : null}
    </Empty>
  );
}

/**
 * 抽屉外框（`presentation="drawer"`）：`Sheet` + 宽抽屉宽度 + 关闭守卫。
 * 只有本文件 import `Sheet*`；标题经呈现 context 渲染成 `SheetTitle`，内容组件不变。
 * - `dirty` 为真时，Esc、点遮罩、关闭图标都先弹 `UnsavedChangesDialog`，确认后才关。
 * - `pending` 为真时一切关闭请求都忽略（SKILL 第 5 步：抽屉里提交中不能取消）。
 */
import type { ReactNode } from "react";

import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { UnsavedChangesDialog, useUnsavedCloseGuard } from "@/components/ui/unsaved-changes-dialog";
import { DetailPresentationContext, type DetailPresentationValue } from "./detail-presentation";
import type { DetailDrawerFrameProps } from "./detail-state";

const DRAWER_PRESENTATION: DetailPresentationValue = { presentation: "drawer", Title: SheetTitle };

/** 宽抽屉：窄屏占满，`sm` 起占 11/12，最宽 `max-w-5xl`。覆盖原语右侧抽屉的 `w-3/4` 与 `sm:max-w-sm`。 */
const DETAIL_DRAWER =
  "data-[side=right]:w-full data-[side=right]:sm:w-11/12 data-[side=right]:sm:max-w-5xl";

export function DetailDrawerFrame({
  open,
  onOpenChange,
  dirty = false,
  pending = false,
  children,
}: Omit<DetailDrawerFrameProps, "presentation"> & { children: ReactNode }) {
  const guard = useUnsavedCloseGuard({ dirty, pending, onClose: () => onOpenChange(false) });
  return (
    <Sheet open={open} onOpenChange={guard.handleOpenChange}>
      <SheetContent side="right" className={DETAIL_DRAWER}>
        <DetailPresentationContext value={DRAWER_PRESENTATION}>
          {/* 上边距给右上角的关闭按钮让位，header 的动作不会被它盖住。 */}
          <div className="flex min-h-0 flex-1 flex-col gap-6 overflow-y-auto px-6 pt-12 pb-6">
            {children}
          </div>
        </DetailPresentationContext>
        <UnsavedChangesDialog {...guard.dialogProps} />
      </SheetContent>
    </Sheet>
  );
}

/**
 * 详情模板的入口（ADR 0013）：一套内容契约，两种外框。
 *
 *   <DetailPage>                                  整页（缺省）
 *   <DetailPage presentation="drawer" open onOpenChange dirty>   抽屉
 *     <DetailHeader … />
 *     <DetailBody tabs={…} aside={…} />
 *   </DetailPage>
 *
 * - props 按 `presentation` 分成联合类型：`open`、`onOpenChange`、`dirty`、`pending` 只在抽屉上合法。
 * - 整页的进场动画由外壳的 `PageTransition` 播（AppShell 已包住每一页），本模板不再包一层。
 *   `DETAIL_MAIN` 导出给路由的 pending 骨架复用：`<div className={DETAIL_MAIN}><DetailSkeleton /></div>`。
 * - 加载中、不存在、出错是三个分支：`DetailSkeleton`、`DetailNotFound`、`DetailError`，两种外框共用。
 *   整页下由路由接（pending / notFound / error），抽屉下由取数状态接（`detailBranch`）。
 * - 模板不取数、不 import 路由库、没有编辑逻辑，也没有页脚。
 */
import type { ReactNode } from "react";

import { DetailDrawerFrame } from "./detail-drawer";
import { type DetailFrameProps, isDrawer } from "./detail-state";

export type {
  DetailBodyProps,
  DetailErrorProps,
  DetailHeaderProps,
  DetailMenuAction,
  DetailNotFoundProps,
  DetailSectionProps,
  DetailTab,
} from "./detail-content";
export {
  DetailBody,
  DetailError,
  DetailHeader,
  DetailNotFound,
  DetailSection,
  DetailSkeleton,
} from "./detail-content";
export { DetailTitle } from "./detail-presentation";
export type {
  DetailBranch,
  DetailDrawerFrameProps,
  DetailFrameProps,
  DetailPageFrameProps,
  DetailPresentation,
} from "./detail-state";
export { detailBranch } from "./detail-state";

/**
 * 整页外框的容器类。路由的 pending 骨架包同一个类，加载完成时位置不跳。
 * `flex-1` 接上外壳内容区的 flex 列，`DetailNotFound`、`DetailError` 的 `Empty` 因此撑满剩余高度。
 */
export const DETAIL_MAIN = "mx-auto flex w-full max-w-6xl flex-1 flex-col gap-6 p-6";

export type DetailPageProps = DetailFrameProps & { children: ReactNode };

export function DetailPage(props: DetailPageProps) {
  if (isDrawer(props)) {
    const { presentation: _presentation, ...drawer } = props;
    return <DetailDrawerFrame {...drawer} />;
  }
  return <div className={DETAIL_MAIN}>{props.children}</div>;
}

/**
 * 呈现 context（ADR 0013）：内容组件里只有标题读它。整页下标题是页面的 `<h1>`，
 * 抽屉下是外框注入的 `SheetTitle`，抽屉因此有可访问名称。本文件不 import `Sheet*`。
 */
import { type ComponentType, createContext, type ReactNode, use } from "react";

import type { DetailPresentation } from "./detail-state";

export type DetailTitleProps = { className?: string; children?: ReactNode };

export type DetailPresentationValue = {
  presentation: DetailPresentation;
  /** 渲染标题的元素。外框提供；缺省是 `<h1>`。 */
  Title: ComponentType<DetailTitleProps>;
};

function PageTitle(props: DetailTitleProps) {
  return <h1 {...props} />;
}

/** 缺省值即整页：整页外框不用再挂 Provider。 */
export const DetailPresentationContext = createContext<DetailPresentationValue>({
  presentation: "page",
  Title: PageTitle,
});

export function useDetailPresentation(): DetailPresentationValue {
  return use(DetailPresentationContext);
}

/**
 * 详情的标题。内容组件一律用它，不直接写 `<h1>` 或 `SheetTitle`。
 * 样式由调用处给全（header、空态、骨架各不相同），本组件不加缺省类。
 */
export function DetailTitle({ className, children }: DetailTitleProps) {
  const { Title } = useDetailPresentation();
  return <Title className={className}>{children}</Title>;
}

/**
 * 详情模板的类型与纯逻辑（ADR 0013）：外框 props 的联合类型、呈现判断、取数状态到三个分支的映射。
 * 不依赖 React 运行时，测试在 detail-state.test.mjs。
 */

/** 呈现：只换外框，内容契约不变。缺省 `"page"`。 */
export type DetailPresentation = "page" | "drawer";

/** 整页（缺省）。`open`、`onOpenChange`、`dirty`、`pending` 只在抽屉上合法，传了 tsc 报错。 */
export type DetailPageFrameProps = {
  presentation?: "page";
  open?: never;
  onOpenChange?: never;
  dirty?: never;
  pending?: never;
};

/** 抽屉：`Sheet` 外框，宽抽屉宽度，带关闭守卫。 */
export type DetailDrawerFrameProps = {
  presentation: "drawer";
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** 编辑态的表单有未保存修改。为真时关闭抽屉先弹 `UnsavedChangesDialog`。 */
  dirty?: boolean;
  /** 编辑态的表单正在提交。为真时 Esc、点遮罩、关闭图标都关不掉抽屉。 */
  pending?: boolean;
};

export type DetailFrameProps = DetailPageFrameProps | DetailDrawerFrameProps;

export function isDrawer(props: DetailFrameProps): props is DetailDrawerFrameProps {
  return props.presentation === "drawer";
}

/** 详情内容的四个分支。加载中、不存在、出错各是一个分支，互不共用。 */
export type DetailBranch = "loading" | "not-found" | "error" | "ready";

/**
 * 取数状态 → 分支。抽屉下由消费者的取数状态接（整页下由路由的 pending / notFound / error 接）。
 * - 有数据就是 `ready`：重新取数中或重新取数失败时，旧数据留在原地。
 * - 没有数据时：出错 → `error`；还在取 → `loading`；取完了 → `not-found`。
 *   取完了没有数据不能再显示「加载中」，否则删掉的记录会永远转圈。
 */
export function detailBranch<TData>({
  isPending,
  error,
  data,
}: {
  isPending: boolean;
  error?: unknown;
  data: TData | null | undefined;
}): DetailBranch {
  if (data !== null && data !== undefined) return "ready";
  if (error !== null && error !== undefined) return "error";
  return isPending ? "loading" : "not-found";
}
